async function run(input, ctx) {
  const files = await ctx.files.list();
  if (!files.includes('flaky.marker')) {
    await ctx.files.write('flaky.marker', 'first attempt');
    throw new Error('transient failure on the first attempt');
  }
  return { recovered: true, marker: await ctx.files.read('flaky.marker') };
}
